<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { cn } from '../../utils.js'; import type { TestResultStatus } from './TestResults.svelte'; import { provideTestSuiteContext } from './context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { name: string; status: TestResultStatus; open?: boolean; defaultOpen?: boolean; onopenchange?: (open: boolean) => void; class?: string; children?: Snippet; } let { name, status, defaultOpen = false, open = $bindable(defaultOpen), onopenchange, class: className = '', children, ...rest }: Props = $props(); provideTestSuiteContext({ get name() { return name; }, get status() { return status; }, get open() { return open; }, setOpen(next) { open = next; onopenchange?.(next); } });</script>
<div {...rest} class={cn('svadmin-ai-tests-part__suite', className)} data-slot="test-suite">{@render children?.()}</div>
